{
    float xDx;
    float xDy;
    float xDz;
    float xDistSq;

    xDx = p_stPoint->xX - p_stSphereCenter->xX;
    xDy = p_stPoint->xY - p_stSphereCenter->xY;
    xDz = p_stPoint->xZ - p_stSphereCenter->xZ;
    xDistSq = (xDx * xDx) + (xDy * xDy) + (xDz * xDz);
    if (xDistSq <= (xSphereRadius * xSphereRadius)) {
        return 1;
    }

    return 0;
}

