void viBufFlush(anon_3* f)
{
    WaitSema(f->sema);
    {
        int value = f->readBytes + 0x7ff;
        if (value < 0)
            value = (value + 0x7ff) >> 11;
        else
            value >>= 11;
        f->readBytes = value << 11;
    }
