    fAlpha = (fAlpha > 1.0f) ? 1.0f : fAlpha;
    fAlpha = (fAlpha < 0.0f) ? 0.0f : fAlpha;
    GLI_BIG_GLOBALS_xGlobalAlpha = fAlpha;
}

