float fn_fUncompressNumber(short n)
{
    unsigned int ulValue;
    unsigned int mantissa;
    int expf;
    unsigned int sign_bit;
    union {
        unsigned int ul;
        float f;
    } value;

    ulValue = n;
    expf = n & 0x7c00;
    sign_bit = n & 0x8000;
    mantissa = n & 0x3ff;
    expf >>= 10;
    if (expf != 0)
    {
        expf += 0x70;
        expf <<= 23;
    }
    mantissa <<= 13;
    sign_bit <<= 16;
    value.ul = sign_bit | expf | mantissa;
    return value.f;
}

